function buildGalleryMarkup(images, lang){
  if(!Array.isArray(images) || images.length===0){
    return "";
  }

  const imageMarkup=images.map((src, index)=>`<figure class="gallery-item"><img src="${src}" alt="${T[lang]["project.gallery"]} ${index + 1}" loading="lazy"><figcaption>${index + 1}</figcaption></figure>`).join("");
  return `<div class="gallery-title">${T[lang]["project.gallery"]}</div><div class="gallery">${imageMarkup}</div>`;
}

async function loadGalleryImages(key){
  const folder=galleryFolders[key];
  if(!folder){ return []; }

  const dirUrl=`assets/images/${folder}/`;

  try {
    const response=await fetch(dirUrl, {cache:"no-store"});
    if(!response.ok){ return []; }

    const html=await response.text();
    const paths=[...html.matchAll(/href=["']([^"']+\.(?:png|jpe?g|gif|webp|svg))["']/gi)]
      .map(match=>match[1].replace(/^\.\//, ""))
      .filter(Boolean);

    const normalized=[...new Set(paths.map(path => path.startsWith("http") ? path : `${dirUrl}${path.replace(/^\//, "")}`))];
    return normalized;
  }catch(error){
    return [];
  }
}

async function openDetail(key){window.currentDetailKey=key;
 const d=details[key], lang=localStorage.getItem("lang")||"en";
 const site=projectLinks[key]||"";
 const siteButton=site?`<a class="project-site-btn" href="${site}" target="_blank" rel="noopener" onclick="event.stopPropagation()">${T[lang]["project.visit"]}</a>`:"";
 const tags=(d.tags[lang]||d.tags.en).map(x=>`<span>${x}</span>`).join("");
 const bodyHtml=(d.body && (d.body[lang] || d.body.en)) || "";
 const galleryImages=await loadGalleryImages(key);
 const galleryMarkup=buildGalleryMarkup(galleryImages, lang);
 document.getElementById("modal-content").innerHTML=`<div class="label">${d.label[lang]}</div><h2>${d.title[lang]}</h2>${bodyHtml}<div class="modal-tags">${tags}</div>${siteButton}${galleryMarkup}`;
 document.getElementById("modal").classList.add("open");document.getElementById("modal").setAttribute("aria-hidden","false");
}
function closeDetail(){document.getElementById("modal").classList.remove("open");document.getElementById("modal").setAttribute("aria-hidden","true")}
document.getElementById("modal").addEventListener("click",e=>{if(e.target.id==="modal")closeDetail()});
document.querySelector(".menu").addEventListener("click",()=>document.querySelector(".nav-links").classList.toggle("open"));
function sendMail(e){e.preventDefault();const n=encodeURIComponent(document.getElementById("name").value),em=encodeURIComponent(document.getElementById("email").value),s=encodeURIComponent(document.getElementById("subject").value),m=encodeURIComponent(document.getElementById("message").value);window.location.href=`mailto:nesrine.bouzid.work@gmail.com?subject=${s}&body=Name:%20${n}%0AEmail:%20${em}%0A%0A${m}`;return false}
